<template>
  <div class="forgot-password-page">
    <div class="forgot-password-container">
      <h2>Reset Password</h2>
      <p class="description">Reset your password using your wallet signature</p>

      <div v-if="isAuthenticated" class="auth-warning">
        <div class="warning-icon">
          <i class="fas fa-exclamation-triangle"></i>
        </div>
        <h3>Already Authenticated</h3>
        <p>This page is only available for unauthenticated users. If you want to change your password, please use the "Change password" option in your profile.</p>
        <router-link to="/my" class="back-link">Go to Profile</router-link>
      </div>

      <div v-else-if="success" class="success-section">
        <div class="success-icon">
          <i class="fas fa-check-circle"></i>
        </div>
        <h3>Password Reset Successful!</h3>
        <p>Your password has been successfully reset. You can now login with your new password.</p>
        <router-link to="/my" class="back-link">Go to Login</router-link>
      </div>

      <div v-else class="form-section">
        <div class="input-group">
          <label>User Tag</label>
          <input 
            type="text" 
            v-model="userTag" 
            placeholder="Enter your user tag"
            :class="{ 'error': userTagError }"
            @input="validateUserTag"
            maxlength="12"
            :disabled="loading"
          >
          <div v-if="userTagError" class="error-message">{{ userTagError }}</div>
        </div>

        <div class="input-group">
          <label>New Password</label>
          <input 
            type="password" 
            v-model="newPassword" 
            placeholder="Enter new password (min 6 characters)"
            :class="{ 'error': passwordError }"
            @input="validatePassword"
            :disabled="loading"
          >
          <div v-if="passwordError" class="error-message">{{ passwordError }}</div>
        </div>

        <div class="wallet-section">
          <p class="wallet-info">Connect your wallet to verify your identity</p>
          <div class="wallet-button-wrapper" @click="handleWalletClick">
            <wallet-multi-button></wallet-multi-button>
          </div>
          <div v-if="walletConnected" class="wallet-status">
            <p class="wallet-info">
              <i class="fas fa-check-circle"></i>
              Wallet Connected: {{ walletAddressShort }}
            </p>
          </div>
        </div>

        <div v-if="error" class="error-message main-error">{{ error }}</div>

        <button 
          @click="handleResetPassword" 
          class="reset-button"
          :disabled="!canSubmit || loading"
        >
          {{ loading ? 'Processing...' : 'Reset Password' }}
        </button>
        
        <button 
          @click="showInfoModal = true" 
          class="more-info-button"
        >
          More Info
        </button>
      </div>

      <!-- Info Modal -->
      <div v-if="showInfoModal" class="info-modal-overlay no-invert" @click.self="showInfoModal = false">
        <div class="info-modal-content">
          <button class="info-modal-close" @click="showInfoModal = false">
            <i class="fas fa-times"></i>
          </button>
          <h3>Password Reset Information</h3>
          <div class="info-modal-body">
            <p>
              You can only reset your password if your account with the specified <strong>userTag</strong> has a linked wallet, and the wallet address matches the one you're connecting.
            </p>
            <p>
              <strong>Why do I need to sign a transaction?</strong>
            </p>
            <p>
              Signing a transaction is required to verify that the wallet you're connecting actually belongs to you. This cryptographic proof ensures that only the owner of the linked wallet can reset the password for the account.
            </p>
            <p>
              The transaction you sign is empty (a transfer of 0 lamports to yourself) and serves only as proof of wallet ownership. It does not cost any fees and does not affect your wallet balance.
            </p>
          </div>
          <div class="info-modal-footer">
            <button class="info-modal-ok-button" @click="showInfoModal = false">Got it</button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, watch, onMounted } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { WalletMultiButton, useWallet } from 'solana-wallets-vue'
import 'solana-wallets-vue/styles.css'
import { Transaction, SystemProgram, PublicKey } from '@solana/web3.js'
import axios from 'axios'
import store from '@/vuex'

const router = useRouter()
const route = useRoute()
const { publicKey, connected } = useWallet()

const userTag = ref('')
const newPassword = ref('')
const userTagError = ref('')
const passwordError = ref('')
const error = ref('')
const loading = ref(false)
const success = ref(false)
const showInfoModal = ref(false)

// Check if user is authenticated
const session = computed(() => store.state.session)
const isAuthenticated = computed(() => session.value?.isAuthenticated || false)

const walletConnected = computed(() => connected.value && publicKey.value)
const walletAddressShort = computed(() => {
  if (!publicKey.value) return ''
  const addr = publicKey.value.toString()
  return addr.slice(0, 4) + '...' + addr.slice(-4)
})

const canSubmit = computed(() => {
  return userTag.value && 
         newPassword.value && 
         newPassword.value.length >= 6 &&
         walletConnected.value &&
         !userTagError.value &&
         !passwordError.value
})

const validateUserTag = () => {
  userTagError.value = ''
  if (!userTag.value) {
    return
  }
  const tagRegex = /^[a-z0-9_-]+$/i
  if (!tagRegex.test(userTag.value)) {
    userTagError.value = 'User tag can only contain letters, numbers, underscores and hyphens'
  } else if (userTag.value.length > 12) {
    userTagError.value = 'User tag must be 12 characters or less'
  }
}

const validatePassword = () => {
  passwordError.value = ''
  if (!newPassword.value) {
    return
  }
  if (newPassword.value.length < 6) {
    passwordError.value = 'Password must be at least 6 characters'
  }
}

// Reset success state when component is mounted or route changes
onMounted(() => {
  success.value = false
  userTag.value = ''
  newPassword.value = ''
  userTagError.value = ''
  passwordError.value = ''
  error.value = ''
})

// Watch for route changes to reset state
watch(() => route.path, () => {
  if (route.path === '/forgot-password') {
    success.value = false
    userTag.value = ''
    newPassword.value = ''
    userTagError.value = ''
    passwordError.value = ''
    error.value = ''
  }
})

// Watch for wallet connection changes
watch(connected, (isConnected) => {
  if (isConnected && publicKey.value) {
    localStorage.setItem('walletAddress', publicKey.value.toString())
  } else {
    localStorage.removeItem('walletAddress')
  }
})

const handleWalletClick = (event) => {
  if (!store.state.disclaimerAgreed) {
    event.preventDefault()
    event.stopPropagation()
    // You can add a disclaimer popup here if needed
  }
}

const createEmptyTransaction = async () => {
  // Create an empty transaction (just a transfer to self with 0 lamports)
  const transaction = new Transaction()
  
  // Add a transfer instruction to self with 0 lamports (essentially empty)
  transaction.add(
    SystemProgram.transfer({
      fromPubkey: publicKey.value,
      toPubkey: publicKey.value,
      lamports: 0
    })
  )

  // Get recent blockhash from backend API
  const blockhashResponse = await axios.post('/solana/blockhash')
  if (!blockhashResponse.data.success) {
    throw new Error(blockhashResponse.data.error || 'Failed to get blockhash')
  }
  const { blockhash } = blockhashResponse.data
  transaction.recentBlockhash = blockhash
  transaction.feePayer = publicKey.value

  return transaction
}

const handleResetPassword = async () => {
  if (!canSubmit.value) return

  error.value = ''
  loading.value = true

  try {
    // Check if wallet is connected
    if (!publicKey.value || !connected.value) {
      throw new Error('Wallet is not connected')
    }

    // Check if Phantom is available
    if (!window.solana || !window.solana.isPhantom) {
      throw new Error('Phantom wallet not found. Please install Phantom extension.')
    }

    // Create empty transaction
    const transaction = await createEmptyTransaction()

    // Sign transaction using Phantom directly
    const signedTransaction = await window.solana.signTransaction(transaction)

    // Serialize signed transaction
    const serializedTransaction = Buffer.from(signedTransaction.serialize()).toString('base64')

    // Send to backend
    const response = await axios.post('/auth/reset-password', {
      userTag: userTag.value,
      newPassword: newPassword.value,
      signedTransaction: serializedTransaction
    })

    if (response.data.success) {
      success.value = true
    } else {
      error.value = response.data.error || 'Failed to reset password'
    }
  } catch (err) {
    console.error('Reset password error:', err)
    error.value = err.response?.data?.error || err.message || 'Failed to reset password'
  } finally {
    loading.value = false
  }
}
</script>

